<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Coach & Clinic</h1><p class="text-muted mb-0">Đăng ký lớp, thanh toán bằng ví và theo dõi trạng thái.</p></div><form class="d-flex gap-2" method="get"><input type="date" name="date" value="<?= esc($date) ?>" class="form-control"><button class="btn btn-outline-secondary">Xem ngày</button></form></div><div class="row g-3"><?php if(!$sessions): ?><div class="col-12"><div class="alert alert-light">Chưa có lớp mở trong ngày này.</div></div><?php endif; ?><?php foreach($sessions as $session): ?><div class="col-md-6"><div class="card h-100 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5 mb-1"><?= esc($session->title) ?></h2><span class="badge text-bg-<?= in_array($session->status,['open','full'],true)?'success':'secondary' ?>"><?= esc($session->status) ?></span></div><div class="text-muted small mb-3"><?= esc($session->coach_name??'-') ?> · <?= esc($session->branch_name??'-') ?> · <?= esc(substr($session->start_time,0,5).'–'.substr($session->end_time,0,5)) ?></div><p class="mb-3">Sức chứa <?= (int)$session->capacity ?> · <?= number_format((float)$session->price_per_player,0,',','.') ?> đ/người</p><?php $entry=$entries[(int)$session->id]??null; ?><?php if($entry): ?><div class="alert alert-info py-2 mb-2">Đăng ký: <?= esc($entry->status) ?><?php if(!empty($entry->invoice_id)): ?><br>Hóa đơn: <?= esc($entry->invoice_status??'unpaid') ?> · <?= number_format((float)($entry->invoice_total_amount??0),0,',','.') ?> đ<?php endif; ?></div><?php if($entry->status==='approved'&&($entry->invoice_status??'')!=='paid'&&!empty($entry->invoice_id)): ?><form method="post" action="<?= base_url('player/coaching/pay/'.$entry->id) ?>"><?= csrf_field() ?><button class="btn btn-success">Thanh toán bằng ví</button></form><?php endif; ?><?php if(in_array($entry->status,['requested','approved','waitlisted'],true)): ?><form method="post" action="<?= base_url('player/coaching/leave/'.$session->id) ?>" class="mt-2"><?= csrf_field() ?><button class="btn btn-outline-secondary">Rời session</button></form><?php endif; ?><?php elseif(in_array($session->status,['open','full'],true)): ?><form method="post" action="<?= base_url('player/coaching/join/'.$session->id) ?>"><?= csrf_field() ?><button class="btn btn-primary"><?= $session->status==='full'?'Vào waitlist':'Đăng ký' ?></button></form><?php endif; ?></div></div></div><?php endforeach; ?></div></div>
